var root = new DirectoryInfo(Environment.CurrentDirectory);
while (root is not null && !File.Exists(Path.Combine(root.FullName, "appsettings.legacy.json")))
    root = root.Parent;
if (root is null) return 1;
if (SettingsReader.ReadTheme(Path.Combine(root.FullName, "appsettings.legacy.json")) != "light") return 1;
if (SettingsReader.ReadTheme(Path.Combine(root.FullName, "appsettings.new.json")) != "dark") return 1;
return 0;
